import three;

size(180);
currentprojection = perspective(6,3,2);

triple A, B, C, P, Q, R;
real t, x, y, z;
real k = 0.4, l = -0.22;

A = (k, l, k^3*k^2 - 4*k*0^2 + 0^3 + 1);
B = (-k/sqrt(4), 0, 1);
P = A + k*dir(180 + l*90);
Q = projection((2,3,4),(4 + 2*(-k/sqrt(4)), 0, 1));
R = 0.4*dir(180 + l*90) + (4,-0.5,-0)^^(0.4,0,1);

draw((4 + 2*(-k/sqrt(4)), 0, 1));
draw((k, l, k^3*k^2 - 4*k*0^2 + 0^3 + 1)--(0,0,0));
draw((0,0,0)--(4 + 2*(-k/sqrt(4)), 0, 1), dashed);
draw((4 + 2*(-k/sqrt(4)), 0, 1)--(2,3,4'' + 2*(-k/sqrt(4)), 0, 1), dashed);
draw((4 + 2*(-k/sqrt(4)), 0, 1)--Q, linewidth(1));
draw((0,-0.5,-4)--(0,0,0)--(2,-0.5,-4), linewidth(1));
draw((0,0,0)--(0,0,1), linewidth(1));
draw((1.8,0,0)--(0,0,0));
